// --- 1. Top-down: memoised recursion. ---
vector<int> memo;                    // sized n+1, filled with a sentinel
int solve(int i) {
    if (i >= n) return 0;            // base case
    if (memo[i] != -1) return memo[i];
    return memo[i] = min(cost[i] + solve(i + 1), cost[i] + solve(i + 2));
}

// --- 2. Bottom-up: tabulation. ---
vector<int> dp(n + 1, 0);            // dp[i] = answer for state i
dp[0] = baseCase;
for (int i = 1; i <= n; i++)         // dependencies ready before use
    dp[i] = combine(dp[i - 1], dp[i - 2]);
return dp[n];

// --- 3. Space-optimised: only the last two states are read. ---
int prev2 = base0, prev1 = base1;
for (int i = 2; i <= n; i++) {
    int cur = combine(prev1, prev2);
    prev2 = prev1;
    prev1 = cur;
}
return prev1;

// --- The two state shapes ---

// "ending exactly at i"  ->  answer is the best over ALL i
int best = INT_MIN, cur = 0;
for (int i = 0; i < n; i++) {
    cur = max(nums[i], cur + nums[i]);          // extend, or start fresh
    best = max(best, cur);
}

// "considering the first i elements"  ->  answer is dp[n]

