def longestPalindrome(s):
    result = ""
    def expand(l, r):
        nonlocal result
        while l >= 0 and r < len(s) and s[l] == s[r]:
            if r - l + 1 > len(result):
                result = s[l:r+1]
            l -= 1; r += 1
    for i in range(len(s)):
        expand(i, i)    # odd
        expand(i, i+1)  # even
    return result

