class Solution {
    public int lengthOfLIS(int[] nums) {
        List<Integer> tails = new ArrayList<>();
        for (int n : nums) {
            int pos = Collections.binarySearch(tails, n);
            if (pos < 0) pos = -(pos + 1);
            if (pos == tails.size()) tails.add(n);
            else tails.set(pos, n);
        }
        return tails.size();
    }
}

